package dev.zomboidmelee.boxing;
import java.util.*;import com.mojang.blaze3d.vertex.VertexConsumer;
/** Same-frame optical reticle capture and world ray, independent of attachment render order. */
public final class Sight34{
 static int depth;static double[]reticle;static double score=Double.POSITIVE_INFINITY;static final List<Runnable>pending=new ArrayList<>();static double[]worldProjection=perspective(70,16d/9);static Object projectionWorld;
 static double[]perspective(double fov,double aspect){double f=1/Math.tan(Math.toRadians(fov/2)),near=.05,far=1024;double[]m=new double[16];m[0]=f/aspect;m[5]=f;m[10]=(far+near)/(near-far);m[11]=-1;m[14]=2*far*near/(near-far);return m;}
 public static void stage(Object e){try{worldProjection=Matrix32.read(R.call(e,"getProjectionMatrix"));projectionWorld=R.get(BoxingClient16.mc(),"level");}catch(IllegalStateException absent){}}
 static double[]projection(){try{return Matrix32.read(R.call(R.type("com.mojang.blaze3d.systems.RenderSystem"),"getProjectionMatrix"));}catch(IllegalStateException absent){return perspective(70,16d/9);}}
 public static void begin(){if(depth++==0){reticle=null;score=Double.POSITIVE_INFINITY;pending.clear();}}
 static boolean active(){return depth>0;}
 public static void end(){if(depth==0)return;if(--depth!=0)return;try{for(Runnable r:List.copyOf(pending))try{r.run();}catch(RuntimeException e){if(!Laser32.warned){Laser32.warned=true;System.err.println("[GlobalMelee34] Deferred laser: "+e);}}}finally{pending.clear();reticle=null;score=Double.POSITIVE_INFINITY;}}
 public static void capture(Object model,Object poses,Object context,Object path){if(!active()||!R.yes(R.call(context,"firstPerson")))return;try{if(!R.yes(R.call(model,"isSight"))&&!R.yes(R.call(model,"isScope")))return;Object mc=BoxingClient16.mc(),p=R.get(mc,"player");if(p==null||Bodycam27.aiming(mc,p,0)<.1)return;Object raw=R.get(model,"divisionNodePaths");if(!(raw instanceof List<?>paths))return;for(Object candidate:paths){if(path!=null&&candidate!=path&&!candidate.equals(path))continue;if(!(candidate instanceof List<?>parts)||parts.isEmpty())continue;R.call(poses,"pushPose");try{for(Object part:opticalPath(model,parts))R.call(part,"translateAndRotateAndScale",poses);double[]eye=Matrix32.mul(Laser32.system(),Laser32.pose(poses)),point=Matrix32.point(eye,0,0,0);if(point[2]>=-.05)continue;double[]ndc=Matrix32.point(projection(),point[0],point[1],point[2]);double s=ndc[0]*ndc[0]+ndc[1]*ndc[1];if(Math.abs(ndc[0])<.9&&Math.abs(ndc[1])<.9&&(s<score||path!=null)){reticle=new double[]{ndc[0],ndc[1]};score=s;}}finally{R.call(poses,"popPose");}}}catch(IllegalStateException absent){}}
 static List<?>opticalPath(Object model,List<?>base){try{Object map=R.get(model,"modelMap");if(map instanceof Map<?,?>nodes){Object illuminated=nodes.get("division_illuminated");if(illuminated!=null){Object found=R.call(model,"getPath",illuminated);if(found instanceof List<?>path&&path.size()>=base.size()&&path.subList(0,base.size()).equals(base))return path;}}}catch(IllegalStateException absent){}return base;}
 static double[]ray(double[]view,double[]projection,double x,double y){double[]inv=Matrix32.inverse(Matrix32.mul(projection,view)),a=Matrix32.point(inv,x,y,-1),b=Matrix32.point(inv,x,y,.999);double dx=b[0]-a[0],dy=b[1]-a[1],dz=b[2]-a[2],n=Math.sqrt(dx*dx+dy*dy+dz*dz);return new double[]{dx/n,dy/n,dz/n};}
 static double[]aim(Object entity,Object level,double[]muzzle,double[]camera){double x=reticle==null?0:reticle[0],y=reticle==null?0:reticle[1];double[]dir=ray(Laser32.view,worldProjection,x,y),far={camera[0]+dir[0]*256,camera[1]+dir[1]*256,camera[2]+dir[2]*256},hit=Laser32.clip(entity,level,camera,far);return Laser32.clip(entity,level,muzzle,hit);}
 static double height(){try{return Math.max(1,R.num(R.call(R.call(BoxingClient16.mc(),"getWindow"),"getHeight")));}catch(IllegalStateException absent){return 1080;}}
 static double[]eyePoint(double[]worldPoint,double[]camera,double[]itemProjection){double[]rel={worldPoint[0]-camera[0],worldPoint[1]-camera[1],worldPoint[2]-camera[2]},ndc=Matrix32.point(Matrix32.mul(worldProjection,Laser32.view),rel[0],rel[1],rel[2]),eye=Matrix32.point(Matrix32.inverse(itemProjection),ndc[0],ndc[1],0);double depth=Math.max(.31,Math.min(8,Math.sqrt(rel[0]*rel[0]+rel[1]*rel[1]+rel[2]*rel[2]))),scale=-depth/eye[2];return new double[]{eye[0]*scale,eye[1]*scale,-depth};}
 static double radius(double depth,double pixels,double physical,double height,double focal){double unit=2*Math.abs(depth)/(Math.max(1,height)*Math.max(.01,Math.abs(focal)));return Math.min(unit*4,Math.max(physical,unit*pixels));}
 static void draw(VertexConsumer v,double[]model,double[]worldEnd,double[]camera,double width,int color,boolean night){double[]system=Laser32.system(),p=projection(),start=Matrix32.point(Matrix32.mul(system,model),0,0,0),end=eyePoint(worldEnd,camera,p);drawEye(v,Matrix32.inverse(system),p,start,end,width,color,night,height());}
 static void drawEye(VertexConsumer v,double[]inverseModelView,double[]projection,double[]start,double[]end,double width,int color,boolean night,double height){double plane=-.08;if(start[2]>=plane&&end[2]>=plane)return;if(start[2]>=plane){double t=(plane-start[2])/(end[2]-start[2]);start=new double[]{start[0]+(end[0]-start[0])*t,start[1]+(end[1]-start[1])*t,plane};}double dx=end[0]-start[0],dy=end[1]-start[1],n=Math.hypot(dx,dy);double[]axis=n>.00001?new double[]{-dy/n,dx/n,0}:new double[]{1,0,0};double a=radius(start[2],night?.65:.45,.0006,height,projection[5]),b=radius(end[2],night?.65:.45,.0006,height,projection[5]);for(int i=0;i<2;i++){double scale=i==0?1:.35;Laser32.quad(v,inverseModelView,Laser32.add(start,axis,-a*scale),Laser32.add(start,axis,a*scale),Laser32.add(end,axis,b*scale),Laser32.add(end,axis,-b*scale),i==0?Laser32.intensity(color,night?.65:.3):color,251);}if(end[2]>-.30)return;double r=radius(end[2],night?1.8:1.35,.0015,height,projection[5]);Laser32.quad(v,inverseModelView,new double[]{end[0]-r,end[1]-r,end[2]},new double[]{end[0]-r,end[1]+r,end[2]},new double[]{end[0]+r,end[1]+r,end[2]},new double[]{end[0]+r,end[1]-r,end[2]},color,251);}
}
